      replyCount: 0,
      isModerated: post.isModerated ?? null,
      isApproved: post.isApproved ?? null,
      createdAt: new Date(),
      updatedAt: new Date(),
    };
    this.forumPosts.set(newPost.id, newPost);
    return newPost;
