      inset 0 1px 0 rgba(255, 255, 255, 0.05);
  }

  .floating:nth-child(2) {
    animation-delay: 2s;
  }

  .floating:nth-child(3) {
    animation-delay: 4s;
  }

  /* Enhanced fade in animations - Professional */
  .fade-in {
    opacity: 0;
    transform: translateY(40px);
    transition: all 0.8s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    animation: fade-in 0.8s ease-out forwards;
  }

  .fade-in.visible {
    opacity: 1;
    transform: translateY(0);
  }

  /* Staggered animation delays for professional sequencing */
  .fade-in:nth-child(1) { animation-delay: 0.1s; }
  .fade-in:nth-child(2) { animation-delay: 0.2s; }
  .fade-in:nth-child(3) { animation-delay: 0.3s; }
  .fade-in:nth-child(4) { animation-delay: 0.4s; }

  /* Hero specific animations */
  .hero-content .fade-in:first-child {
    animation-delay: 0.2s;
  }

  .hero-illustration {
    animation: slide-up 1s ease-out 0.5s both;
  }

  /* Respect reduced motion for fade-ins */
  @media (prefers-reduced-motion: reduce) {
    .fade-in {
      transition: none;
      transform: none;
      opacity: 1;
    }

    .fade-in.visible {
      opacity: 1;
      transform: none;
    }
  }

  /* Professional Button Styling - Enhanced */
  .btn-professional {
    @apply relative font-semibold transition-all duration-300 ease-out;
    box-shadow: 0 4px 12px rgba(66, 165, 245, 0.25), 0 2px 4px rgba(66, 165, 245, 0.15);
    background: linear-gradient(135deg, hsl(214, 73%, 59%) 0%, hsl(214, 80%, 65%) 100%);
    border: 1px solid rgba(66, 165, 245, 0.3);
  }

  .btn-professional:hover {
    @apply transform -translate-y-1;
    box-shadow: 0 8px 24px rgba(66, 165, 245, 0.35), 0 4px 12px rgba(66, 165, 245, 0.25);
    background: linear-gradient(135deg, hsl(214, 80%, 62%) 0%, hsl(214, 85%, 68%) 100%);
  }

  .btn-professional:active {
    @apply transform translate-y-0;
    box-shadow: 0 2px 8px rgba(66, 165, 245, 0.3);
  }

  .dark .btn-professional {
    background: linear-gradient(135deg, hsl(214, 80%, 72%) 0%, hsl(214, 85%, 75%) 100%);
    color: hsl(222, 84%, 3%);
    box-shadow: 0 4px 16px rgba(66, 165, 245, 0.4), 0 2px 8px rgba(66, 165, 245, 0.25);
    border: 1px solid rgba(66, 165, 245, 0.5);
  }

  .dark .btn-professional:hover {
    background: linear-gradient(135deg, hsl(214, 85%, 75%) 0%, hsl(214, 90%, 78%) 100%);
    box-shadow: 0 8px 32px rgba(66, 165, 245, 0.5), 0 4px 16px rgba(66, 165, 245, 0.35);
  }

  /* Secondary Button Styling */
  .btn-secondary-outline {
    @apply relative font-semibold transition-all duration-300 ease-out;
    background: rgba(255, 255, 255, 0.8);
    backdrop-filter: blur(8px);
    border: 2px solid hsl(214, 73%, 59%);
    color: hsl(214, 73%, 59%);
    box-shadow: 0 4px 12px rgba(66, 165, 245, 0.15), inset 0 1px 0 rgba(255, 255, 255, 0.4);
  }

  .btn-secondary-outline:hover {
    @apply transform -translate-y-1;
    background: hsl(214, 73%, 59%);
    color: white;
    box-shadow: 0 8px 24px rgba(66, 165, 245, 0.25), 0 4px 12px rgba(66, 165, 245, 0.15);
  }

  .dark .btn-secondary-outline {
    background: rgba(34, 38, 51, 0.85);
    backdrop-filter: blur(12px);
    border: 2px solid hsl(214, 80%, 72%);
    color: hsl(214, 80%, 72%);
    box-shadow: 0 4px 16px rgba(66, 165, 245, 0.25), inset 0 1px 0 rgba(255, 255, 255, 0.05);
  }

  .dark .btn-secondary-outline:hover {
    background: hsl(214, 80%, 72%);
    color: hsl(222, 84%, 3%);
    box-shadow: 0 8px 32px rgba(66, 165, 245, 0.35), 0 4px 16px rgba(66, 165, 245, 0.25);
  }

  /* Trust Indicators - Professional Styling */
  .trust-indicator {
    @apply flex items-center space-x-3 p-4 rounded-xl transition-all duration-300;
    background: rgba(255, 255, 255, 0.7);
    backdrop-filter: blur(8px);
    border: 1px solid rgba(34, 197, 94, 0.2);
    box-shadow: 0 2px 8px rgba(34, 197, 94, 0.1);
  }

  .trust-indicator:hover {
    @apply transform -translate-y-1;
    background: rgba(255, 255, 255, 0.85);
    box-shadow: 0 4px 16px rgba(34, 197, 94, 0.15);
  }

  .dark .trust-indicator {
    background: rgba(34, 38, 51, 0.7);
    backdrop-filter: blur(12px);
    border: 1px solid rgba(34, 197, 94, 0.3);
    box-shadow: 0 2px 12px rgba(34, 197, 94, 0.15);
  }

  .dark .trust-indicator:hover {
    background: rgba(34, 38, 51, 0.85);
    box-shadow: 0 4px 20px rgba(34, 197, 94, 0.25);
  }

  .trust-checkmark {
    @apply flex-shrink-0 w-6 h-6 rounded-full flex items-center justify-center;
    background: linear-gradient(135deg, hsl(145, 70%, 55%) 0%, hsl(145, 75%, 60%) 100%);
    box-shadow: 0 2px 8px rgba(34, 197, 94, 0.3);
  }

  .dark .trust-checkmark {
    background: linear-gradient(135deg, hsl(145, 70%, 65%) 0%, hsl(145, 75%, 70%) 100%);
    box-shadow: 0 2px 12px rgba(34, 197, 94, 0.4);
  }

  /* Micro-interactions */
  .bounce-hover:hover {
    animation: bounce-subtle 0.6s ease-in-out;
  }

  /* Hero Illustration Enhancement */
  .hero-illustration {
    @apply relative rounded-3xl overflow-hidden;
    background: linear-gradient(145deg, 
      rgba(255, 255, 255, 0.9) 0%, 
      rgba(255, 255, 255, 0.7) 100%);
    backdrop-filter: blur(16px);
    border: 1px solid rgba(255, 255, 255, 0.4);
    box-shadow: 
      0 8px 32px rgba(66, 165, 245, 0.15),
      0 4px 16px rgba(66, 165, 245, 0.1),
      inset 0 1px 0 rgba(255, 255, 255, 0.6);
    transform: perspective(1000px) rotateY(-5deg) rotateX(5deg);
    transition: all 0.6s ease;
  }

  .hero-illustration:hover {
    transform: perspective(1000px) rotateY(-2deg) rotateX(2deg) translateY(-8px);
    box-shadow: 
      0 12px 48px rgba(66, 165, 245, 0.2),
      0 6px 24px rgba(66, 165, 245, 0.15),
      inset 0 1px 0 rgba(255, 255, 255, 0.7);
  }

  .dark .hero-illustration {
    background: linear-gradient(145deg, 
      rgba(34, 38, 51, 0.9) 0%, 
      rgba(30, 35, 48, 0.95) 100%);
    backdrop-filter: blur(20px);
    border: 1px solid rgba(66, 165, 245, 0.2);
    box-shadow: 
      0 8px 32px rgba(0, 0, 0, 0.4),
      0 4px 16px rgba(0, 0, 0, 0.3),
      inset 0 1px 0 rgba(255, 255, 255, 0.05);
  }

  .dark .hero-illustration:hover {
    box-shadow: 
      0 12px 48px rgba(0, 0, 0, 0.5),
      0 6px 24px rgba(66, 165, 245, 0.2),
      inset 0 1px 0 rgba(255, 255, 255, 0.08);
  }

  .scale-breath {
    animation: scale-breath 3s ease-in-out infinite;
  }

  .shimmer-bg {
    background: linear-gradient(
      90deg,
      transparent,
      rgba(255, 255, 255, 0.1),
      transparent
    );
    background-size: 200px 100%;
    animation: shimmer 2s infinite;
  }

  /* Chat bubble styles */
  .chat-bubble-user {
    @apply bg-primary text-primary-foreground rounded-2xl rounded-br-md px-4 py-3 max-w-[80%] ml-auto;
  }

  .chat-bubble-ai {
    @apply bg-muted text-foreground rounded-2xl rounded-bl-md px-4 py-3 max-w-[80%] mr-auto;
  }

  /* Custom scrollbar */
  .custom-scrollbar {
    scrollbar-width: thin;
    scrollbar-color: hsl(var(--muted-foreground)) transparent;
  }

  .custom-scrollbar::-webkit-scrollbar {
    width: 6px;
  }

  .custom-scrollbar::-webkit-scrollbar-track {
    background: transparent;
  }

  .custom-scrollbar::-webkit-scrollbar-thumb {
    background-color: hsl(var(--muted-foreground));
    border-radius: 3px;
  }

  .custom-scrollbar::-webkit-scrollbar-thumb:hover {
    background-color: hsl(var(--foreground));
  }

  /* Loading animations */
  .loading-dots {
    display: inline-flex;
    gap: 4px;
  }

  .loading-dots div {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background-color: currentColor;
    animation: loading-dots 1.4s infinite ease-in-out both;
  }

  .loading-dots div:nth-child(1) { animation-delay: -0.32s; }
  .loading-dots div:nth-child(2) { animation-delay: -0.16s; }
  .loading-dots div:nth-child(3) { animation-delay: 0s; }

  /* Emergency styles */
  .emergency-pulse {
    animation: emergency-pulse 2s infinite;
  }

  /* Assessment progress */
  .assessment-progress {
    @apply w-full bg-muted rounded-full h-2;
  }

  .assessment-progress-bar {
    @apply h-2 bg-primary rounded-full transition-all duration-300 ease-in-out;
  }
}

@layer utilities {
  /* Enhanced Text Utilities */
  .text-gradient-primary {
    background: var(--gradient-primary);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    font-weight: var(--font-weight-semibold);
  }

  .text-gradient-secondary {
    background: var(--gradient-secondary);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    font-weight: var(--font-weight-semibold);
  }

  .text-gradient-accent {
    background: var(--gradient-accent);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    font-weight: var(--font-weight-semibold);
  }

  /* Professional Typography Classes */
  .text-heading-xl {
    font-family: var(--font-heading);
    font-size: clamp(2.5rem, 5vw, 4rem);
    font-weight: var(--font-weight-bold);
    line-height: var(--line-height-tight);
    letter-spacing: var(--letter-spacing-tight);
  }

  .text-heading-lg {
    font-family: var(--font-heading);
    font-size: clamp(2rem, 4vw, 3rem);
    font-weight: var(--font-weight-semibold);
    line-height: var(--line-height-tight);
  }

  .text-heading-md {
    font-family: var(--font-heading);
    font-size: clamp(1.5rem, 3vw, 2.25rem);
    font-weight: var(--font-weight-semibold);
    line-height: var(--line-height-snug);
  }

  .text-body-lg {
    font-size: 1.125rem;
    line-height: var(--line-height-relaxed);
    font-weight: var(--font-weight-normal);
  }

  .text-body {
    font-size: 1rem;
    line-height: var(--line-height-relaxed);
    font-weight: var(--font-weight-normal);
  }

  .text-caption {
    font-size: 0.875rem;
    line-height: var(--line-height-normal);
    font-weight: var(--font-weight-medium);
  }

  /* Enhanced accessibility for dark theme text */
  .dark .text-heading-xl,
  .dark .text-heading-lg,
  .dark .text-heading-md {
    color: hsl(210, 40%, 98%);
    text-shadow: 0 1px 2px rgba(0, 0, 0, 0.15);
  }

  .dark .text-body-lg,
  .dark .text-body {
    color: hsl(210, 30%, 88%);
    text-shadow: 0 0.5px 1px rgba(0, 0, 0, 0.1);
  }

  /* Remove text shadows on low-DPI screens for better contrast */
  @media (-webkit-max-device-pixel-ratio: 1), (max-resolution: 96dpi) {
    .dark .text-heading-xl,
    .dark .text-heading-lg,
    .dark .text-heading-md,
    .dark .text-body-lg,
    .dark .text-body {
      text-shadow: none;
    }
  }

  .dark .text-caption {
    color: hsl(210, 25%, 82%);
  }

  /* Enhanced glass effects for professional look */
  .glass {
    @apply bg-white/10 backdrop-blur-md border border-white/20;
    box-shadow: 0 4px 16px rgba(255, 255, 255, 0.1);
  }

  .glass-dark {
    @apply bg-black/20 backdrop-blur-md border border-white/10;
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.3);
  }

  /* Professional button styling for dark theme */
  .btn-professional {
    @apply inline-flex items-center justify-center rounded-lg px-6 py-3 font-medium transition-all duration-200;
    box-shadow: var(--shadow-sm);
  }

  .btn-professional:hover {
    @apply transform -translate-y-0.5;
    box-shadow: var(--shadow-md);
  }

  .dark .btn-professional {
    box-shadow: 
      0 2px 8px rgba(0, 0, 0, 0.4),
      0 1px 3px rgba(0, 0, 0, 0.3);
  }

  .dark .btn-professional:hover {
    box-shadow: 
      0 4px 16px rgba(0, 0, 0, 0.5),
      0 2px 8px rgba(0, 0, 0, 0.4);
  }

  /* Professional section backgrounds */
  .section-primary {
    background: var(--section-primary, var(--background));
  }

  .section-secondary {
    background: var(--section-secondary, var(--muted));
  }

  .section-accent {
    background: var(--section-accent, var(--card));
  }

  /* Enhanced text readability for dark theme */
  .text-enhanced {
    @apply text-foreground;
    text-shadow: 0 1px 2px rgba(0, 0, 0, 0.1);
  }

  .dark .text-enhanced {
    text-shadow: 0 1px 3px rgba(0, 0, 0, 0.5);
  }

  /* Professional border styles */
  .border-professional {
    border: 1px solid var(--border);
  }

  .dark .border-professional {
    border: 1px solid hsl(222, 40%, 18%);
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.05);
  }
}

/* Professional Keyframe Animations */
@keyframes float {
  0%, 100% { 
    transform: translateY(0px); 
  }
  50% { 
    transform: translateY(-20px); 
  }
}

@keyframes float-delayed {
  0%, 100% { 
    transform: translateY(0px) rotate(0deg); 
  }
  50% { 
    transform: translateY(-15px) rotate(2deg); 
  }
}

@keyframes loading-dots {
  0%, 80%, 100% {
    transform: scale(0);
  }
  40% {
    transform: scale(1);
  }
}

@keyframes emergency-pulse {
  0% {
    box-shadow: 0 0 0 0 rgba(239, 68, 68, 0.7);
  }
  70% {
    box-shadow: 0 0 0 10px rgba(239, 68, 68, 0);
  }
  100% {
    box-shadow: 0 0 0 0 rgba(239, 68, 68, 0);
  }
}

@keyframes pulse-soft {
  0%, 100% { 
    opacity: 0.4; 
  }
  50% { 
    opacity: 0.8; 
  }
}

@keyframes fade-in {
  from { 
    opacity: 0; 
    transform: translateY(20px); 
  }
  to { 
    opacity: 1; 
    transform: translateY(0); 
  }
}


@keyframes slide-up {
  from {
    opacity: 0;
    transform: translateY(50px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}


@keyframes bounce-subtle {
  0%, 100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-4px);
  }
}

@keyframes shimmer {
  0% {
    background-position: -200px 0;
  }
  100% {
    background-position: 200px 0;
  }
}

@keyframes rotate-slow {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}

@keyframes scale-breath {
  0%, 100% {
    transform: scale(1);
  }
  50% {
    transform: scale(1.05);
  }
}

@keyframes parallax-slow {
  0% {
    transform: translateY(0px);
  }
  100% {
    transform: translateY(-50px);
  }
}

@keyframes parallax-medium {
  0% {
    transform: translateY(0px);
  }
  100% {
    transform: translateY(-30px);
  }
}

@keyframes parallax-fast {
  0% {
    transform: translateY(0px);
  }
  100% {
    transform: translateY(-15px);
  }
}

@keyframes float-gentle {
  0%, 100% { 
    transform: translateY(0px) scale(1); 
  }
  50% { 
    transform: translateY(-15px) scale(1.02); 
  }
}

@keyframes float-gentle-reverse {
  0%, 100% { 
    transform: translateY(0px) rotate(0deg); 
  }
  50% { 
    transform: translateY(10px) rotate(2deg); 
  }
}

/* Responsive design helpers */
@media (max-width: 768px) {
  .mobile-hide {
    display: none;
  }

  .mobile-full {
    width: 100%;
  }

  .mobile-stack {
    flex-direction: column;
  }
}

/* Accessibility improvements - Comprehensive motion reduction */
@media (prefers-reduced-motion: reduce) {
  /* Disable all custom animation classes */
  .floating,
  .floating-delayed,
  .card-hover,
  .fade-in,
  .shimmer-bg,
  .emergency-pulse,
  .bounce-hover,
  .scale-breath,
  .loading-dots,
  .loading-dots div,
  *[class*="parallax-"],
  *[class*="rotate-"],
  *[class*="bounce-"],
  *[class*="scale-"],
  *[class*="float"],
  *[class*="pulse-"],
  *[class*="slide-"],
  *[class*="fade-"],
  *[class*="accordion-"] {
    animation: none !important;
    transition: none !important;
    transform: none !important;
  }

  /* Disable all Tailwind animation utilities */
  *[class*="animate-"],
  *[class*="transition-"],
  *[class*="duration-"],
  *[class*="ease-"],
  *[class*="delay-"] {
    animation: none !important;
    transition: none !important;
  }

  /* Force disable all animations and transitions globally */
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    transition-delay: 0s !important;
    scroll-behavior: auto !important;
  }

  /* Preserve focus styles but remove transitions */
  *:focus {
    transition: none !important;
  }

  /* Ensure hover states are instant */
  *:hover {
    transition: none !important;
  }
}

/* Enhanced High Contrast Support for Accessibility */
@media (prefers-contrast: high) {
  :root {
    --border: hsl(0, 0%, 40%);
    --muted-foreground: hsl(0, 0%, 20%);
    --primary: hsl(214, 100%, 50%);
    --secondary: hsl(145, 100%, 40%);
  }

  .dark {
    --background: hsl(0, 0%, 0%);
    --foreground: hsl(0, 0%, 100%);
    --card: hsl(0, 0%, 10%);
    --card-foreground: hsl(0, 0%, 100%);
    --border: hsl(0, 0%, 60%);
    --muted-foreground: hsl(0, 0%, 90%);
    --primary: hsl(214, 100%, 70%);
    --secondary: hsl(145, 100%, 60%);
  }
}

/* Enhanced Color Contrast for Better Accessibility */
@media (prefers-contrast: more) {
  .dark {
    --foreground: hsl(0, 0%, 100%);
    --muted-foreground: hsl(0, 0%, 95%);
    --border: hsl(0, 0%, 50%);
    --primary: hsl(214, 100%, 75%);
    --secondary: hsl(145, 100%, 65%);
  }
}

/* Enhanced Focus states for accessibility (WCAG 2.4.7) */
.focus-ring {
  @apply focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-offset-2 focus-visible:ring-offset-background;
}

/* High-contrast focus ring for dark mode */
.dark .focus-ring {
  @apply focus-visible:ring-blue-400 focus-visible:ring-offset-gray-900;
}

/* Base focus-visible styles for all interactive elements */
button:focus-visible,
a:focus-visible,
input:focus-visible,
textarea:focus-visible,
select:focus-visible,
[role="button"]:focus-visible,
[role="link"]:focus-visible,
[role="tab"]:focus-visible,
[tabindex]:focus-visible {
  outline: 2px solid hsl(var(--ring));
  outline-offset: 2px;
}

/* Enhanced focus styles for dark mode with high contrast */
.dark button:focus-visible,
.dark a:focus-visible,
.dark input:focus-visible,
.dark textarea:focus-visible,
.dark select:focus-visible,
.dark [role="button"]:focus-visible,
.dark [role="link"]:focus-visible,
.dark [role="tab"]:focus-visible,
.dark [tabindex]:focus-visible {
  outline: 3px solid hsl(214, 80%, 72%);
  outline-offset: 2px;
  box-shadow: 0 0 0 1px hsl(222, 84%, 3%), 0 0 0 4px hsl(214, 80%, 72%);
}

/* Specific high-contrast focus for cards and complex components */
.dark .card-professional:focus-visible,
.dark .feature-tile:focus-visible {
  outline: 3px solid hsl(214, 80%, 72%);
  outline-offset: 3px;
  box-shadow: 
    0 0 0 1px hsl(222, 84%, 3%), 
    0 0 0 6px hsl(214, 80%, 72%),
    0 8px 32px rgba(66, 165, 245, 0.3);
}

/* Print styles */
@media print {
  .no-print {
    display: none !important;
  }

  .print-block {
    display: block !important;
  }
}

