                      </CardTitle>
                    </CardHeader>
                    <CardContent>
                      {counselorsLoading ? (
                        <div className="grid md:grid-cols-2 gap-4">
                          {[...Array(4)].map((_, i) => (
                            <div key={i} className="animate-pulse">
                              <div className="bg-muted h-32 rounded-lg"></div>
                            </div>
                          ))}
                        </div>
                      ) : (
                        <div className="grid md:grid-cols-2 gap-4">
                          {counselors?.map((counselor: Counselor) => (
                            <Card
                              key={counselor.id}
