import { useState, useEffect } from "react";
import { Link, useLocation } from "wouter";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Sheet, SheetContent, SheetTrigger } from "@/components/ui/sheet";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Switch } from "@/components/ui/switch";
import { Separator } from "@/components/ui/separator";
import { 
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
  DropdownMenuSub,
  DropdownMenuSubContent,
  DropdownMenuSubTrigger
} from "@/components/ui/dropdown-menu";
import { 
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator 
} from "@/components/ui/breadcrumb";
import { 
  Brain, 
  Home, 
  MessageCircle, 
  Calendar, 
  ClipboardList, 
  BookOpen, 
  Users, 
  BarChart3, 
  Info,
  Menu,
  Bell,
  User,
  ChevronDown,
  Globe,
  Settings,
  LogOut,
  Heart,
  ArrowLeft,
  PhoneCall,
  Shield,
  Bot,
  Wifi,
  WifiOff,
  Signal,
  UserCircle,
  Lock,
  Volume2,
  VolumeX,
  Palette,
  BellOff,
  Eye,
  EyeOff,
  Maximize,
  Minimize,
  Languages
} from "lucide-react";
import { cn } from "@/lib/utils";
import type { User as UserType } from "@/types";

/**
 * Connection quality and status types for chat functionality
 */
export type ConnectionQuality = 'excellent' | 'good' | 'fair' | 'poor' | 'disconnected';
export type ConnectionStatus = 'connected' | 'connecting' | 'reconnecting' | 'disconnected';

/**
 * Header component props interface
 */
export interface HeaderProps {
  // Chat-specific props (optional)
  isChatMode?: boolean;
  currentUser?: UserType | null;
  isAnonymousMode?: boolean;

  // Connection and AI status for chat
  connectionStatus?: ConnectionStatus;
  connectionQuality?: ConnectionQuality;
  aiModel?: string;

  // UI state for chat
  isFullscreen?: boolean;
  isSoundEnabled?: boolean;
  isNotificationsEnabled?: boolean;
  selectedLanguage?: string;

  // Event handlers for chat
  onEmergencyClick?: () => void;
  onSettingsChange?: (setting: string, value: any) => void;
  onNavigateBack?: () => void;
  onToggleFullscreen?: () => void;
  onToggleAnonymousMode?: (enabled: boolean) => void;
  onProfileClick?: () => void;
  onLogout?: () => void;
}

/**
 * Header Component - Enhanced with chat-specific features for mental health platform
 * Features responsive design, chat mode detection, and comprehensive mental health support
 */
export default function Header({
  isChatMode = false,
  currentUser,
  isAnonymousMode = false,
  connectionStatus = 'connected',
  connectionQuality = 'excellent',
  aiModel = "Gemini Pro",
  isFullscreen = false,
  isSoundEnabled = true,
  isNotificationsEnabled = true,
  selectedLanguage = "English",
  onEmergencyClick,
  onSettingsChange,
  onNavigateBack,
  onToggleFullscreen,
  onToggleAnonymousMode,
  onProfileClick,
  onLogout
}: HeaderProps = {}) {
  const [location] = useLocation();
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [hasScrolled, setHasScrolled] = useState(false);
  const [showPrivacyBanner, setShowPrivacyBanner] = useState(isChatMode);

  // Handle scroll shadow effect
  useEffect(() => {
    const handleScroll = () => {
      setHasScrolled(window.scrollY > 10);
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  // Connection quality indicator configuration for chat mode
  const getConnectionIndicator = () => {
    const indicators = {
      excellent: { color: "bg-green-500", strength: 4, text: "Excellent" },
      good: { color: "bg-green-400", strength: 3, text: "Good" },
      fair: { color: "bg-yellow-500", strength: 2, text: "Fair" },
      poor: { color: "bg-orange-500", strength: 1, text: "Poor" },
      disconnected: { color: "bg-red-500", strength: 0, text: "Disconnected" }
    };
    return indicators[connectionQuality];
  };

  const getConnectionStatusText = () => {
    switch (connectionStatus) {
      case 'connected': return 'Online';
      case 'connecting': return 'Connecting...';
      case 'reconnecting': return 'Reconnecting...';
      case 'disconnected': return 'Offline';
      default: return 'Unknown';
    }
  };

  // Language options for chat mode
  const languages = [
    { code: 'en', name: 'English' },
    { code: 'es', name: 'Español' },
    { code: 'fr', name: 'Français' },
    { code: 'zh', name: '中文' },
    { code: 'ar', name: 'العربية' }
  ];

  const currentLanguage = languages.find(lang => lang.name === selectedLanguage) || languages[0];
  const connectionIndicator = getConnectionIndicator();

  // Navigation items configuration - Crisis Help removed as requested by user
  const navItems = [
    { 
      path: "/", 
      label: "Home", 
      icon: Home, 
      active: location === "/" 
    },
    { 
      path: "/chatbot", 
      label: "AI Support", 
      icon: MessageCircle, 
      active: location === "/chatbot" 
    },
    { 
      path: "/appointments", 
      label: "Counseling", 
      icon: Calendar, 
      active: location === "/appointments" 
    },
    { 
      path: "/assessments", 
      label: "Assessment", 
      icon: ClipboardList, 
      active: location === "/assessments" 
    },
    { 
      path: "/resources", 
      label: "Resources", 
      icon: BookOpen, 
      active: location === "/resources" 
    },
    { 
      path: "/peer-support", 
      label: "Community", 
      icon: Users, 
      active: location === "/peer-support" 
    },
    { 
      path: "/dashboard", 
      label: "Dashboard", 
      icon: BarChart3, 
      active: location === "/dashboard" 
    },
    { 
      path: "/about", 
      label: "About", 
      icon: Info, 
      active: location === "/about" 
    },
  ];

