/**
 * Appointments Routes - Counselor booking and appointment management endpoints
 * 
 * This module handles all appointment-related API endpoints including:
 * - Counselor availability and listing
 * - Appointment creation, updating, and cancellation
 * - Date range queries for counselor schedules
 * - User appointment history
 * 
 * Features:
 * - Real-time availability checking
 * - Conflict prevention for double-booking
 * - Comprehensive appointment lifecycle management
 * - Integration with counselor availability system
 */

import type { Express } from "express";
import { storage } from "../storage";
import { insertAppointmentSchema } from "@shared/schema";

/**
 * Register appointment routes with the Express app
 * @param app - Express application instance
 */
export function registerAppointmentRoutes(app: Express): void {
  /**
   * Get All Counselors Endpoint
   * GET /api/counselors
   * 
   * Retrieves all available counselors for appointment booking.
   * Only returns counselors who are currently accepting appointments.
   * 
   * @returns {Array} List of available counselors with their details
   */
  app.get("/api/counselors", async (req, res) => {
    try {
      const counselors = await storage.getCounselors();
      res.json(counselors);
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  /**
   * Get Available Counselors Endpoint
   * GET /api/counselors/available
   * 
   * Retrieves only counselors who are currently available for new appointments.
   * This endpoint filters out counselors who may be temporarily unavailable.
   * 
   * @returns {Array} List of currently available counselors
   */
  app.get("/api/counselors/available", async (req, res) => {
    try {
      const counselors = await storage.getAvailableCounselors();
      res.json(counselors);
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  /**
   * Create New Appointment Endpoint
   * POST /api/appointments
   * 
   * Creates a new appointment between a user and counselor.
   * Validates that both user and counselor exist and counselor is available.
   * Prevents double-booking through database constraints.
   * 
   * @body {Object} appointmentData - Appointment details (user, counselor, date/time)
   * @returns {Object} Created appointment object
   */
  app.post("/api/appointments", async (req, res) => {
    try {
      const appointmentData = insertAppointmentSchema.parse(req.body);
      const appointment = await storage.createAppointment(appointmentData);
      res.json(appointment);
    } catch (error: any) {
      res.status(400).json({ message: error.message });
    }
  });

  /**
   * Get User Appointments Endpoint
   * GET /api/appointments/user/:userId
   * 
   * Retrieves all appointments for a specific user,
   * ordered by date (most recent first) for easy review.
   * 
   * @param userId - User ID to fetch appointments for
   * @returns {Array} List of user's appointments with counselor details
   */
  app.get("/api/appointments/user/:userId", async (req, res) => {
    try {
      const appointments = await storage.getAppointments(req.params.userId);
      res.json(appointments);
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  /**
   * Get Counselor Schedule Endpoint
   * GET /api/appointments/counselor/:counselorId
   * 
   * Retrieves appointments for a specific counselor within a date range.
   * Used for availability checking and schedule management.
   * 
   * @param counselorId - Counselor ID to fetch schedule for
   * @query startDate - Start date for the query range
   * @query endDate - End date for the query range
   * @returns {Array} List of appointments in the specified date range
   */
  app.get("/api/appointments/counselor/:counselorId", async (req, res) => {
    try {
      const { startDate, endDate } = req.query;
      const appointments = await storage.getAppointmentsByDateRange(
        req.params.counselorId,
        new Date(startDate as string),
        new Date(endDate as string)
      );
      res.json(appointments);
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  /**
   * Update Appointment Endpoint
   * PATCH /api/appointments/:id
   * 
   * Updates an existing appointment with new details.
   * Supports partial updates (only modified fields need to be provided).
   * 
   * @param id - Appointment ID to update
   * @body {Object} updates - Partial appointment data to update
   * @returns {Object} Updated appointment object
   */
  app.patch("/api/appointments/:id", async (req, res) => {
    try {
      const appointment = await storage.updateAppointment(req.params.id, req.body);
      res.json(appointment);
    } catch (error: any) {
      res.status(400).json({ message: error.message });
    }
  });

  /**
   * Cancel Appointment Endpoint
   * DELETE /api/appointments/:id
   * 
   * Cancels an existing appointment by marking it as cancelled.
   * This maintains appointment history while freeing up the time slot.
   * 
   * @param id - Appointment ID to cancel
   * @returns {Object} Confirmation message
   */
  app.delete("/api/appointments/:id", async (req, res) => {
    try {
      await storage.cancelAppointment(req.params.id);
      res.json({ message: "Appointment cancelled" });
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });
}

server/routes/assessments.ts.content:
/**
 * Assessments Routes - Mental health assessment endpoints
 * 
 * This module handles all assessment-related API endpoints including:
 * - Creating and storing mental health assessments (PHQ-9, GAD-7, GHQ)
 * - AI-powered analysis of assessment results
 * - User assessment history retrieval
 * - Latest assessment tracking for progress monitoring
 * 
 * Features:
 * - Integration with OpenAI for intelligent assessment analysis
 * - Support for multiple standardized assessment types
 * - Automatic interpretation and recommendation generation
 * - Progress tracking across multiple assessments
 */

import type { Express } from "express";
import { storage } from "../storage";
import { analyzeAssessmentResults } from "../services/openai";
import { insertAssessmentSchema } from "@shared/schema";

/**
 * Register assessment routes with the Express app
 * @param app - Express application instance
 */
export function registerAssessmentRoutes(app: Express): void {
  /**
   * Create New Assessment Endpoint
   * POST /api/assessments
   * 
   * Processes completed mental health assessments and generates AI analysis.
   * 
   * This endpoint:
   * 1. Validates assessment data using Zod schema
   * 2. Analyzes results using OpenAI for interpretation and recommendations
   * 3. Stores assessment with AI-generated insights
   * 4. Returns complete assessment with analysis
   * 
   * @body {Object} assessmentData - Assessment responses and metadata
   * @returns {Object} Complete assessment with AI analysis and recommendations
   */
  app.post("/api/assessments", async (req, res) => {
    try {
      const assessmentData = insertAssessmentSchema.parse(req.body);

      // Analyze results with AI for intelligent interpretation
      // Convert Json type to any[] for OpenAI function compatibility
      const responses = Array.isArray(assessmentData.responses) 
        ? assessmentData.responses as any[]
        : assessmentData.responses 
          ? [assessmentData.responses] 
          : [];

      // Generate AI-powered analysis with interpretation and recommendations
      const analysis = await analyzeAssessmentResults(
        assessmentData.assessmentType,
        responses,
        assessmentData.totalScore
      );

      // Store assessment with AI-generated insights
      const assessment = await storage.createAssessment({
        ...assessmentData,
        interpretation: analysis.interpretation,
        recommendations: analysis.recommendations
      });

      res.json(assessment);
    } catch (error: any) {
      res.status(400).json({ message: error.message });
    }
  });

  /**
   * Get User Assessments Endpoint
   * GET /api/assessments/user/:userId
   * 
   * Retrieves all assessments completed by a specific user,
   * ordered by completion date (most recent first) for progress tracking.
   * 
   * @param userId - User ID to fetch assessments for
   * @returns {Array} List of user's assessments with analysis and recommendations
   */
  app.get("/api/assessments/user/:userId", async (req, res) => {
    try {
      const assessments = await storage.getAssessments(req.params.userId);
      res.json(assessments);
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  /**
   * Get Latest Assessment by Type Endpoint
   * GET /api/assessments/latest/:userId/:type
   * 
   * Retrieves the most recent assessment of a specific type for a user.
   * Useful for tracking progress and showing current status for each assessment type.
   * 
   * @param userId - User ID to fetch assessment for
   * @param type - Assessment type (PHQ-9, GAD-7, GHQ, etc.)
   * @returns {Object} Most recent assessment of the specified type
   */
  app.get("/api/assessments/latest/:userId/:type", async (req, res) => {
    try {
      const assessment = await storage.getLatestAssessment(req.params.userId, req.params.type);
      res.json(assessment);
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });
}

server/routes/auth.ts.content:
/**
 * Authentication Routes - User registration and login endpoints
 * 
 * This module handles all authentication-related API endpoints including:
 * - User registration with password hashing
 * - User login with credential validation
 * - Security measures including bcrypt password hashing
 * 
 * All endpoints follow security best practices:
 * - Passwords are hashed with high salt rounds (12)
 * - Passwords are never returned in API responses
 * - Input validation using Zod schemas
 * - Proper error handling with appropriate HTTP status codes
 */

import type { Express } from "express";
import * as bcrypt from "bcrypt";
import { storage } from "../storage";
import { insertUserSchema } from "@shared/schema";

/**
 * Register authentication routes with the Express app
 * @param app - Express application instance
 */
export function registerAuthRoutes(app: Express): void {
  /**
   * User Registration Endpoint
   * POST /api/auth/register
   * 
   * Creates a new user account with encrypted password storage.
   * Validates that email is unique before creating the account.
   * 
   * @body {Object} userData - User registration data (validated by insertUserSchema)
   * @returns {Object} User object without password field
   */
  app.post("/api/auth/register", async (req, res) => {
    try {
      const userData = insertUserSchema.parse(req.body);
      const existingUser = await storage.getUserByEmail(userData.email);

      if (existingUser) {
        return res.status(400).json({ message: "User already exists" });
      }

      // Security: Hash password before storing in database
      const saltRounds = 12; // High salt rounds for security
      const hashedPassword = await bcrypt.hash(userData.password, saltRounds);

      const user = await storage.createUser({
        ...userData,
        password: hashedPassword
      });

      // Security: Never return password in response
      res.json({ user: { id: user.id, username: user.username, email: user.email } });
    } catch (error: any) {
      res.status(400).json({ message: error.message });
    }
  });

  /**
   * User Login Endpoint
   * POST /api/auth/login
   * 
   * Authenticates user credentials and returns user information.
   * Uses bcrypt to verify password against stored hash.
   * 
   * @body {Object} credentials - Login credentials { email, password }
   * @returns {Object} User object without password field
   */
  app.post("/api/auth/login", async (req, res) => {
    try {
      const { email, password } = req.body;

      // Input validation: Ensure email and password are provided
      if (!email || !password) {
        return res.status(400).json({ message: "Email and password are required" });
      }

      const user = await storage.getUserByEmail(email);

      // Security: Use bcrypt to compare hashed passwords
      if (!user || !(await bcrypt.compare(password, user.password))) {
        return res.status(401).json({ message: "Invalid credentials" });
      }

      // Security: Never return password in response
      res.json({ user: { id: user.id, username: user.username, email: user.email } });
    } catch (error: any) {
      res.status(400).json({ message: error.message });
    }
  });
}

server/routes/chat.ts.content:
/**
 * Chat Routes - AI chatbot conversation endpoints
 * 
 * This module handles all chat-related API endpoints including:
 * - Creating and managing chat conversations
 * - Sending and retrieving chat messages
 * - AI response generation through OpenAI integration
 * - Automatic conversation title generation
 * 
 * Features:
 * - Real-time messaging support
 * - AI-powered responses with context awareness
 * - Conversation history management
 * - Automatic title generation for new conversations
 */

import type { Express } from "express";
import { storage } from "../storage";
import { generateChatResponse, generateConversationTitle } from "../services/openai";
import { insertChatConversationSchema, insertChatMessageSchema } from "@shared/schema";

/**
 * Register chat routes with the Express app
 * @param app - Express application instance
 */
export function registerChatRoutes(app: Express): void {
  /**
   * Get User Conversations Endpoint
   * GET /api/chat/conversations/:userId
   * 
   * Retrieves all chat conversations for a specific user,
   * ordered by most recent activity.
   * 
   * @param userId - User ID to fetch conversations for
   * @returns {Array} List of chat conversations
   */
  app.get("/api/chat/conversations/:userId", async (req, res) => {
    try {
      const conversations = await storage.getChatConversations(req.params.userId);
      res.json(conversations);
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  /**
   * Create New Conversation Endpoint
   * POST /api/chat/conversations
   * 
   * Creates a new chat conversation for a user.
   * Used when starting a new chat session.
   * 
   * @body {Object} conversationData - Conversation creation data
   * @returns {Object} Created conversation object
   */
  app.post("/api/chat/conversations", async (req, res) => {
    try {
      const conversationData = insertChatConversationSchema.parse(req.body);
      const conversation = await storage.createChatConversation(conversationData);
      res.json(conversation);
    } catch (error: any) {
      res.status(400).json({ message: error.message });
    }
  });

  /**
   * Get Conversation Messages Endpoint
   * GET /api/chat/messages/:conversationId
   * 
   * Retrieves all messages in a specific conversation,
   * ordered chronologically for proper chat display.
   * 
   * @param conversationId - Conversation ID to fetch messages for
   * @returns {Array} List of chat messages in chronological order
   */
  app.get("/api/chat/messages/:conversationId", async (req, res) => {
    try {
      const messages = await storage.getChatMessages(req.params.conversationId);
      res.json(messages);
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  /**
   * Send Chat Message Endpoint
   * POST /api/chat/message
   * 
   * Processes new chat messages and generates AI responses.
   * This is the core endpoint for chat functionality:
   * 
   * 1. Validates and stores user message
   * 2. If it's a user message, generates AI response using conversation history
   * 3. Stores AI response and returns both messages
   * 4. Updates conversation title for new conversations
   * 
   * @body {Object} messageData - Message data with conversationId, role, content
   * @returns {Object} User message and AI response with suggestions
   */
  app.post("/api/chat/message", async (req, res) => {
    try {
      const messageData = insertChatMessageSchema.parse(req.body);

      // Security: Validate conversationId BEFORE any database operations
      if (!messageData.conversationId) {
        return res.status(400).json({ message: "Conversation ID is required" });
      }

      // Security: Verify conversation exists before creating message
      // Note: The storage method createChatMessage has comprehensive validation
      const message = await storage.createChatMessage(messageData);

      // If it's a user message, generate AI response using conversation context
      if (messageData.role === 'user') {
        const conversationHistory = await storage.getChatMessages(messageData.conversationId);
        const historyForAI = conversationHistory.map(msg => ({
          role: msg.role,
          content: msg.content
        }));

        // Generate contextual AI response using OpenAI service
        const aiResponse = await generateChatResponse(messageData.content, historyForAI);

        // Save AI response to conversation
        const aiMessage = await storage.createChatMessage({
          conversationId: messageData.conversationId,
          role: 'assistant',
          content: aiResponse.message
        });

        // Auto-generate conversation title for first exchange to improve UX
        if (conversationHistory.length <= 2) {
          const title = await generateConversationTitle([messageData.content]);
          await storage.updateConversationTitle(messageData.conversationId, title);
        }

        res.json({ 
          userMessage: message, 
          aiMessage, 
          suggestions: aiResponse.suggestions, 
          escalation: aiResponse.escalation 
        });
      } else {
        res.json({ message });
      }
    } catch (error: any) {
      res.status(400).json({ message: error.message });
    }
  });
}

server/routes/emergency.ts.content:
/**
 * Emergency Routes - Crisis intervention and emergency contact endpoints
 * 
 * This module handles all emergency and crisis-related API endpoints including:
 * - Emergency contact information retrieval
 * - Crisis hotline and support service management
 * - Country-specific emergency resources
 * - Crisis contact management with priority ordering
 * 
 * Features:
 * - Immediate access to crisis intervention resources
 * - Geographic/country-specific emergency contacts
 * - Multiple contact methods (phone, SMS, chat, text)
 * - Priority-based contact ordering for urgent situations
 * - Real-time availability status for emergency services
 */

import type { Express } from "express";
import { storage } from "../storage";
import { insertCrisisContactSchema } from "@shared/schema";

/**
 * Register emergency routes with the Express app
 * @param app - Express application instance
 */
export function registerEmergencyRoutes(app: Express): void {
  /**
   * Get Emergency Contacts Endpoint
   * GET /api/emergency/contacts
   * 
   * Retrieves general emergency contacts and crisis intervention resources.
   * These are immediate-access contacts for users experiencing mental health emergencies.
   * 
   * @returns {Array} List of active emergency contacts
   */
  app.get("/api/emergency/contacts", async (req, res) => {
    try {
      const contacts = await storage.getEmergencyContacts();
      res.json(contacts);
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  /**
   * Get Crisis Contacts with Country Filter Endpoint
   * GET /api/crisis/contacts
   * 
   * Retrieves crisis intervention contacts with optional country filtering.
   * This endpoint provides localized emergency resources that are relevant
   * to the user's geographic location and language preferences.
   * 
   * @query country - Optional country code filter for localized resources
   * @returns {Array} List of crisis contacts ordered by priority
   */
  app.get("/api/crisis/contacts", async (req, res) => {
    try {
      const { country } = req.query;
      const contacts = await storage.getCrisisContacts(country as string);
      res.json(contacts);
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  /**
   * Get Specific Crisis Contact Endpoint
   * GET /api/crisis/contacts/:id
   * 
   * Retrieves detailed information for a specific crisis contact.
   * Used when users need complete contact details including
   * multiple contact methods and availability information.
   * 
   * @param id - Crisis contact ID to retrieve
   * @returns {Object} Complete crisis contact information
   */
  app.get("/api/crisis/contacts/:id", async (req, res) => {
    try {
      const contact = await storage.getCrisisContact(req.params.id);
      if (!contact) {
        return res.status(404).json({ message: "Crisis contact not found" });
      }
      res.json(contact);
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  /**
   * Get Crisis Contacts by Type Endpoint
   * GET /api/crisis/contacts/type/:type
   * 
   * Retrieves crisis contacts filtered by service type (hotline, chat, text, etc.).
   * Allows users to find contacts based on their preferred communication method
   * or specific type of crisis support needed.
   * 
   * @param type - Contact type filter (hotline, chat, text, emergency, etc.)
   * @query country - Optional country filter for localized results
   * @returns {Array} List of crisis contacts of the specified type
   */
  app.get("/api/crisis/contacts/type/:type", async (req, res) => {
    try {
      const { country } = req.query;
      const contacts = await storage.getCrisisContactsByType(req.params.type, country as string);
      res.json(contacts);
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  /**
   * Create Crisis Contact Endpoint
   * POST /api/crisis/contacts
   * 
   * Creates a new crisis contact resource.
   * This endpoint is typically used by administrators to add new
   * emergency resources and crisis intervention services.
   * 
   * @body {Object} contactData - Crisis contact information with validation
   * @returns {Object} Created crisis contact object
   */
  app.post("/api/crisis/contacts", async (req, res) => {
    try {
      const contactData = insertCrisisContactSchema.parse(req.body);
      const contact = await storage.createCrisisContact(contactData);
      res.status(201).json(contact);
    } catch (error: any) {
      res.status(400).json({ message: error.message });
    }
  });

  /**
   * Update Crisis Contact Endpoint
   * PUT /api/crisis/contacts/:id
   * 
   * Updates an existing crisis contact with new information.
   * Supports partial updates to keep emergency resources current
   * and accurate for users in crisis situations.
   * 
   * @param id - Crisis contact ID to update
   * @body {Object} updates - Partial contact data to update
   * @returns {Object} Updated crisis contact object
   */
  app.put("/api/crisis/contacts/:id", async (req, res) => {
    try {
      const updates = req.body; // Partial update, no need for full schema validation
      const contact = await storage.updateCrisisContact(req.params.id, updates);
      if (!contact) {
        return res.status(404).json({ message: "Crisis contact not found" });
      }
      res.json(contact);
    } catch (error: any) {
      res.status(400).json({ message: error.message });
    }
  });

  /**
   * Get Active Crisis Contacts Endpoint
   * GET /api/crisis/contacts/active/:country?
   * 
   * Retrieves only currently active crisis contacts.
   * This endpoint ensures users only see emergency resources
   * that are currently operational and available for immediate help.
   * 
   * @param country - Optional country parameter for localized active contacts
   * @returns {Array} List of currently active crisis contacts
   */
  app.get("/api/crisis/contacts/active/:country?", async (req, res) => {
    try {
      const country = req.params.country;
      const contacts = await storage.getActiveCrisisContacts(country);
      res.json(contacts);
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });
}

