/**
 * Server-side Type Definitions
 * 
 * This module defines types that are specific to the server-side application
 * and are not shared with the client. These types help ensure type safety
 * throughout the server codebase and provide clear interfaces for services.
 * 
 * Organization:
 * - API Request/Response types
 * - Service layer types
 * - Configuration types
 * - Error handling types
 * - WebSocket message types
 */

/**
 * API Response wrapper type for consistent response formatting
 */
export interface ApiResponse<T = any> {
  success: boolean;
  data?: T;
  message?: string;
  error?: string;
  timestamp: string;
}

/**
 * Error response structure for consistent error handling
 */
export interface ErrorResponse {
  success: false;
  error: string;
  message: string;
  statusCode: number;
  timestamp: string;
  details?: any;
}

/**
 * Pagination parameters for list endpoints
 */
export interface PaginationParams {
  page: number;
  limit: number;
  offset: number;
}

/**
 * Paginated response wrapper
 */
export interface PaginatedResponse<T> {
  items: T[];
  pagination: {
    page: number;
    limit: number;
    total: number;
    totalPages: number;
    hasNext: boolean;
    hasPrev: boolean;
  };
}

/**
