import { useState, useRef, useEffect, useCallback } from "react";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Avatar, AvatarFallback } from "@/components/ui/avatar";
import { 
  Send, 
  Bot,
  User as UserIcon,
  Loader2
} from "lucide-react";
import { cn } from "@/lib/utils";
import type { ChatMessage } from "@/types";

interface ChatInterfaceProps {
  conversationId: string;
  messages: ChatMessage[];
  isLoading: boolean;
  onSendMessage: (content: string, context?: any) => void;
  isSending: boolean;
  onToggleSidebar: () => void;
}

/**
 * Simple Chat Interface Component for Mental Health Support
 * Clean, minimal design inspired by ChatGPT, WhatsApp, and iMessage
 */
export default function ChatInterface({
  conversationId,
  messages,
  isLoading,
  onSendMessage,
  isSending,
  onToggleSidebar
}: ChatInterfaceProps) {
  const [inputValue, setInputValue] = useState("");

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLTextAreaElement>(null);

  // Auto-scroll to bottom when new messages arrive
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  // Auto-focus input
  useEffect(() => {
    if (inputRef.current && !window.matchMedia('(max-width: 768px)').matches) {
      inputRef.current.focus();
    }
  }, [conversationId]);

  const handleSendMessage = useCallback(() => {
    const content = inputValue.trim();
    if (!content) return;

    onSendMessage(content);
    setInputValue("");
  }, [inputValue, onSendMessage]);

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage();
    }
  };

  const formatTime = (timestamp: string | Date) => {
    const date = typeof timestamp === 'string' ? new Date(timestamp) : timestamp;
    return date.toLocaleTimeString([], { 
      hour: '2-digit', 
      minute: '2-digit' 
    });
  };

  return (
    <div className="flex flex-col h-full bg-white dark:bg-gray-900">

      {/* Messages Area */}
      <div className="flex-1 overflow-hidden">
        <ScrollArea className="h-full px-4 py-6">
          <div className="max-w-4xl mx-auto space-y-4">

            {/* Welcome Message */}
            {messages.length === 0 && (
              <div className="text-center py-12">
                <div className="w-16 h-16 mx-auto mb-4 rounded-full bg-blue-100 dark:bg-blue-900/30 flex items-center justify-center">
                  <Bot className="h-8 w-8 text-blue-600 dark:text-blue-400" />
                </div>
                <h2 className="text-xl font-semibold text-gray-900 dark:text-white mb-2">
                  Welcome to MindCare AI
                </h2>
                <p className="text-gray-600 dark:text-gray-400 max-w-md mx-auto">
                  I'm here to support you with your mental health. 
                  Feel free to share what's on your mind.
                </p>
              </div>
            )}

            {/* Chat Messages */}
            {messages.map((message, index) => {
              const isUser = message.role === "user";
              const showAvatar = !isUser && (index === 0 || messages[index - 1]?.role === "user");

              return (
                <div
                  key={message.id}
                  className={cn(
                    "flex gap-3 max-w-[80%]",
                    isUser ? "ml-auto flex-row-reverse" : "mr-auto"
                  )}
                  data-testid={`message-${message.id}`}
                >

                  {/* Avatar (only for AI messages, and only when needed) */}
                  {!isUser && (
                    <div className="flex-shrink-0">
                      {showAvatar ? (
                        <Avatar className="h-8 w-8">
                          <AvatarFallback className="bg-blue-600 text-white">
                            <Bot className="h-4 w-4" />
                          </AvatarFallback>
                        </Avatar>
                      ) : (
                        <div className="w-8" />
                      )}
                    </div>
                  )}

                  {/* Message Bubble */}
                  <div
                    className={cn(
                      "rounded-2xl px-4 py-3 max-w-full",
                      isUser
                        ? "bg-gray-100 dark:bg-gray-700 text-gray-900 dark:text-white rounded-br-md"
                        : "bg-blue-50 dark:bg-blue-900/30 text-gray-900 dark:text-white rounded-bl-md"
                    )}
                  >
                    <p className="text-sm leading-relaxed whitespace-pre-wrap">
                      {message.content}
                    </p>

                    {/* Timestamp */}
                    <div className={cn(
                      "text-xs text-gray-500 dark:text-gray-400 mt-1",
                      isUser ? "text-right" : "text-left"
                    )}>
                      {formatTime(message.timestamp)}
                    </div>
                  </div>

                  {/* User Avatar (minimal) */}
                  {isUser && (
                    <div className="flex-shrink-0">
                      <Avatar className="h-8 w-8">
                        <AvatarFallback className="bg-gray-600 text-white">
                          <UserIcon className="h-4 w-4" />
                        </AvatarFallback>
                      </Avatar>
                    </div>
                  )}
                </div>
              );
            })}

            {/* Typing Indicator */}
            {isSending && (
              <div className="flex gap-3 max-w-[80%] mr-auto">
                <Avatar className="h-8 w-8">
                  <AvatarFallback className="bg-blue-600 text-white">
                    <Bot className="h-4 w-4" />
                  </AvatarFallback>
                </Avatar>
                <div className="bg-blue-50 dark:bg-blue-900/30 rounded-2xl rounded-bl-md px-4 py-3">
                  <div className="flex items-center space-x-1">
                    <div className="flex space-x-1">
                      <div className="w-2 h-2 bg-blue-400 rounded-full animate-bounce" />
                      <div className="w-2 h-2 bg-blue-400 rounded-full animate-bounce" style={{ animationDelay: '0.1s' }} />
                      <div className="w-2 h-2 bg-blue-400 rounded-full animate-bounce" style={{ animationDelay: '0.2s' }} />
                    </div>
                    <span className="text-xs text-gray-500 dark:text-gray-400 ml-2">
                      AI is typing...
                    </span>
                  </div>
                </div>
              </div>
            )}

            <div ref={messagesEndRef} />
          </div>
        </ScrollArea>
      </div>

      {/* Input Area */}
      <div className="border-t border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-900">
        <div className="max-w-4xl mx-auto p-4">
          <div className="flex items-end space-x-3">

            {/* Text Input */}
            <div className="flex-1 relative">
              <Textarea
                ref={inputRef}
                value={inputValue}
                onChange={(e) => setInputValue(e.target.value)}
                onKeyPress={handleKeyPress}
                placeholder="How are you feeling today?"
                className={cn(
                  "min-h-[44px] max-h-32 resize-none rounded-2xl border-gray-300 dark:border-gray-600",
                  "bg-gray-50 dark:bg-gray-800 focus:bg-white dark:focus:bg-gray-700",
                  "placeholder:text-gray-500 dark:placeholder:text-gray-400",
                  "pr-12"
                )}
                disabled={isSending}
                rows={1}
                data-testid="input-message"
              />

              {/* Send Button (appears when typing) */}
              {inputValue.trim() && (
                <Button
                  onClick={handleSendMessage}
                  disabled={isSending || !inputValue.trim()}
                  className="absolute right-2 bottom-2 h-8 w-8 rounded-full bg-blue-600 hover:bg-blue-700 p-0"
                  data-testid="button-send-message"
                  aria-label="Send message"
                >
                  {isSending ? (
                    <Loader2 className="h-4 w-4 animate-spin" />
                  ) : (
                    <Send className="h-4 w-4" />
                  )}
                </Button>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

client/src/pages/peer-support/components.content:
import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Textarea } from "@/components/ui/textarea";
import { Separator } from "@/components/ui/separator";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { 
  Heart, 
  MessageCircle, 
  Flag, 
  Clock, 
  ChevronUp,
  Send,
  User,
  Eye,
  MoreVertical
} from "lucide-react";
import { apiRequest } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";
import { cn } from "@/lib/utils";
import type { ForumPost as ForumPostType, ForumReply } from "@/types";

interface ForumPostProps {
  post: ForumPostType;
  onUpvote: (postId: string) => void;
  className?: string;
  "data-testid"?: string;
}

/**
 * Forum Post Component - Individual post display with replies
 * Features upvoting, replying, reporting, and moderation status
 */
export default function ForumPost({ 
  post, 
  onUpvote, 
  className,
  "data-testid": testId
}: ForumPostProps) {
  const [isRepliesOpen, setIsRepliesOpen] = useState(false);
  const [isReplyDialogOpen, setIsReplyDialogOpen] = useState(false);
  const [replyContent, setReplyContent] = useState("");
  const [hasUpvoted, setHasUpvoted] = useState(false);

  const queryClient = useQueryClient();
  const { toast } = useToast();

  // Mock user ID - in production would come from auth context
  const userId = "mock-user-id";

  // Fetch replies for this post with proper typing and default empty array
  const { data: replies = [], isLoading: repliesLoading } = useQuery<ForumReply[]>({
    queryKey: [`/api/forum/posts/${post.id}/replies`],
    enabled: isRepliesOpen,
  });

  // Create reply mutation
  const createReplyMutation = useMutation({
    mutationFn: async (content: string) => {
      const response = await apiRequest("POST", "/api/forum/replies", {
        postId: post.id,
        userId,
        content,
        isAnonymous: true
      });
      return await response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: [`/api/forum/posts/${post.id}/replies`] });
      setReplyContent("");
      setIsReplyDialogOpen(false);
      toast({
        title: "Reply Posted",
        description: "Your reply has been submitted and is awaiting moderation.",
      });
    },
    onError: () => {
      toast({
        title: "Error",
        description: "Failed to post reply. Please try again.",
        variant: "destructive",
      });
    },
  });

  const handleUpvote = () => {
    if (!hasUpvoted) {
      onUpvote(post.id);
      setHasUpvoted(true);
    }
  };

  const handleReply = () => {
    if (replyContent.trim().length < 10) {
      toast({
        title: "Reply too short",
        description: "Please write at least 10 characters.",
        variant: "destructive",
      });
      return;
    }
    createReplyMutation.mutate(replyContent);
  };

  const handleReport = () => {
    toast({
      title: "Post Reported",
      description: "Thank you for helping keep our community safe. Moderators will review this post.",
    });
  };

  // Get time ago string
  const getTimeAgo = (date: Date) => {
    const now = new Date();
    const diffMs = now.getTime() - new Date(date).getTime();
    const diffMins = Math.floor(diffMs / 60000);
    const diffHours = Math.floor(diffMins / 60);
    const diffDays = Math.floor(diffHours / 24);

    if (diffMins < 1) return "Just now";
    if (diffMins < 60) return `${diffMins}m ago`;
    if (diffHours < 24) return `${diffHours}h ago`;
    if (diffDays < 7) return `${diffDays}d ago`;
    return new Date(date).toLocaleDateString();
  };

  return (
    <Card className={cn("hover:shadow-md transition-shadow", className)} data-testid={testId}>
      <CardContent className="p-6">
        <div className="space-y-4">
          {/* Post Header */}
          <div className="flex items-start justify-between">
            <div className="flex items-center space-x-3">
              <div className="w-8 h-8 rounded-full bg-gradient-to-br from-primary to-secondary flex items-center justify-center">
                <User className="text-white" size={16} />
              </div>
              <div>
                <p className="font-medium text-foreground">
                  {post.isAnonymous ? "Anonymous Student" : "Student"}
                </p>
                <div className="flex items-center space-x-2 text-sm text-muted-foreground">
                  <Clock size={12} />
                  <span>{getTimeAgo(post.createdAt)}</span>
                  {post.category && (
                    <>
                      <span>•</span>
                      <Badge 
                        variant="secondary" 
                        className="text-xs"
                        style={{ backgroundColor: post.category.color + "20", color: post.category.color }}
                      >
                        {post.category.name}
                      </Badge>
                    </>
                  )}
                </div>
              </div>
            </div>

            {/* Moderation Status */}
            <div className="flex items-center space-x-2">
              {post.isApproved ? (
                <Badge variant="secondary" className="bg-green-100 text-green-800">
                  Approved
                </Badge>
              ) : (
                <Badge variant="secondary" className="bg-yellow-100 text-yellow-800">
                  Pending Review
                </Badge>
              )}
              <Button size="icon" variant="ghost" onClick={handleReport} data-testid={`button-report-${post.id}`}>
                <MoreVertical size={16} />
              </Button>
            </div>
          </div>

          {/* Post Content */}
          <div className="space-y-3">
            <h3 className="text-lg font-semibold text-foreground">{post.title}</h3>
            <p className="text-foreground whitespace-pre-wrap leading-relaxed">{post.content}</p>
          </div>

          {/* Post Actions */}
          <div className="flex items-center justify-between pt-2 border-t border-border">
            <div className="flex items-center space-x-4">
              <Button
                variant="ghost"
                size="sm"
                className={cn(
                  "flex items-center space-x-2",
                  hasUpvoted && "text-primary bg-primary/10"
                )}
                onClick={handleUpvote}
                disabled={hasUpvoted}
                data-testid={`button-upvote-${post.id}`}
              >
                <ChevronUp size={16} />
                <span>{post.upvotes + (hasUpvoted ? 1 : 0)}</span>
              </Button>

              <Button
                variant="ghost"
                size="sm"
                className="flex items-center space-x-2"
                onClick={() => setIsRepliesOpen(!isRepliesOpen)}
                data-testid={`button-replies-${post.id}`}
              >
                <MessageCircle size={16} />
                <span>{post.replyCount} replies</span>
              </Button>

              <Dialog open={isReplyDialogOpen} onOpenChange={setIsReplyDialogOpen}>
                <DialogTrigger asChild>
                  <Button variant="ghost" size="sm" data-testid={`button-reply-${post.id}`}>
                    Reply
                  </Button>
                </DialogTrigger>
                <DialogContent>
                  <DialogHeader>
                    <DialogTitle className="font-heading">Reply to Post</DialogTitle>
                  </DialogHeader>
                  <div className="space-y-4">
                    <div className="bg-muted/50 p-4 rounded-lg">
                      <p className="text-sm font-medium text-foreground">{post.title}</p>
                      <p className="text-sm text-muted-foreground line-clamp-3">{post.content}</p>
                    </div>

                    <Textarea
                      placeholder="Write your supportive response..."
                      value={replyContent}
                      onChange={(e) => setReplyContent(e.target.value)}
                      className="min-h-[100px]"
                      data-testid="textarea-reply-content"
                    />

                    <div className="flex space-x-2">
                      <Button 
                        onClick={handleReply}
                        disabled={createReplyMutation.isPending || replyContent.trim().length < 10}
                        className="gradient-primary text-white"
                        data-testid="button-submit-reply"
                      >
                        <Send size={16} className="mr-2" />
                        {createReplyMutation.isPending ? "Posting..." : "Post Reply"}
                      </Button>
                      <Button 
                        variant="outline"
                        onClick={() => setIsReplyDialogOpen(false)}
                        data-testid="button-cancel-reply"
                      >
                        Cancel
                      </Button>
                    </div>
                  </div>
                </DialogContent>
              </Dialog>
            </div>

            <Button
              variant="ghost"
              size="sm"
              className="text-muted-foreground hover:text-destructive"
              onClick={handleReport}
              data-testid={`button-report-post-${post.id}`}
            >
              <Flag size={14} className="mr-1" />
              Report
            </Button>
          </div>

          {/* Replies Section */}
          {isRepliesOpen && (
            <div className="mt-6 pt-6 border-t border-border">
              <h4 className="font-medium text-foreground mb-4">Replies ({post.replyCount})</h4>

              {repliesLoading ? (
                <div className="space-y-4">
                  {[...Array(3)].map((_, i) => (
                    <div key={i} className="animate-pulse">
                      <div className="bg-muted h-20 rounded-lg"></div>
                    </div>
                  ))}
                </div>
              ) : replies && replies.length > 0 ? (
                <div className="space-y-4">
                  {replies.map((reply: ForumReply) => (
                    <div key={reply.id} className="bg-muted/30 rounded-lg p-4">
                      <div className="flex items-start justify-between mb-2">
                        <div className="flex items-center space-x-2">
                          <div className="w-6 h-6 rounded-full bg-gradient-to-br from-secondary to-accent flex items-center justify-center">
                            <User className="text-white" size={12} />
                          </div>
                          <span className="text-sm font-medium text-foreground">
                            {reply.isAnonymous ? "Anonymous Student" : "Student"}
                          </span>
                          <span className="text-xs text-muted-foreground">
                            {getTimeAgo(reply.createdAt)}
                          </span>
                        </div>

                        <div className="flex items-center space-x-2">
                          <Button size="icon" variant="ghost" className="h-6 w-6">
                            <ChevronUp size={12} />
                          </Button>
                          <span className="text-xs text-muted-foreground">{reply.upvotes}</span>
                        </div>
                      </div>
                      <p className="text-sm text-foreground whitespace-pre-wrap">{reply.content}</p>
                    </div>
                  ))}
                </div>
              ) : (
                <p className="text-sm text-muted-foreground italic">No replies yet. Be the first to respond!</p>
              )}
            </div>
          )}
        </div>
      </CardContent>
    </Card>
  );
}

